import * as THREE from 'three/webgpu';
import { texture, uv, vec4, float, mix, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-primary-cta';

  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const imageUrl = '/prism-mock/home/nodes/orb-decor.png';
  const map = ctx.textureLoader.load(imageUrl);
  map.colorSpace = THREE.SRGBColorSpace;

  const uvNode = uv();
  const texNode = texture(map, uvNode);

  // subtle engineered gradient overlay + grain-like vignette using ink/accent tones
  const inkColor = vec4(0x16 / 255, 0x16 / 255, 0x1d / 255, 1.0);
  const accentColor = vec4(0xff / 255, 0x2a / 255, 0x38 / 255, 1.0);

  const gradientMix = uniform(0.12);
  const vignette = float(1.0).sub(
    uvNode.sub(0.5).length().mul(0.6)
  ).clamp(0.0, 1.0);

  const gradientLayer = mix(inkColor, accentColor, uvNode.y.clamp(0.0, 1.0));
  const composed = mix(texNode, gradientLayer, gradientMix).mul(vignette.mul(0.25).add(0.75));

  material.colorNode = vec4(composed.rgb, texNode.a);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'home-primary-cta-plane';
  group.add(mesh);

  group.position.set(0, -2.85, 0.2);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return group;
}
